56	    localparam
57	        S_IDLE = 0,
58	        S_PRE_BACK = 1,
59	        S_BACK = 2,
60	        S_FILL = 3,
61	        S_WAIT = 4;
62	
63	    reg [2:0]state = 0;
64	    reg [2:0]next_state = 0;
65	    reg [ELEMENT_WORDS_WIDTH-1:0]word_count = 0;
66	    reg [ELEMENT_WORDS_WIDTH-1:0]next_word_count = 0;
