68	
69	    always @ (posedge clk) begin
70	        if (rst) begin
71	            state <= S_IDLE;
72	            word_count <= 2'b00;
73	        end
74	        else begin
75	            state <= next_state;
76	            word_count <= next_word_count;
77	        end
78	    end
79	
80	    // state ctrl
81	    always @ (*) begin
82	        if (rst) begin
83	            next_state = S_IDLE;
84	            next_word_count = 2'b00;
85	        end
86	        else begin
87	            case (state)
88	                S_IDLE: begin
89	                    if (en_r || en_w) begin
90	                        if (cache_hit)
91	                            next_state = S_IDLE;
92	                        else if (cache_valid && cache_dirty)
93	                            next_state = S_PRE_BACK;
94	                        else
95	                            next_state = S_FILL;
96	                    end
97	                    next_word_count = 2'b00;
98	                end
99	
100	                S_PRE_BACK: begin
101	                    next_state = S_BACK;
102	                    next_word_count = 2'b00;
103	                end
104	
105	                S_BACK: begin
106	                    if (mem_ack_i && word_count == {ELEMENT_WORDS_WIDTH{1'b1}})    // 2'b11 in default case
107	                        next_state = S_FILL;
108	                    else
109	                        next_state = S_BACK;
110	
111	                    if (mem_ack_i)
112	                        next_word_count = word_count + 1'b1;
113	                    else
114	                        next_word_count = word_count;
115	                end
116	
117	                S_FILL: begin
118	                    if (mem_ack_i && word_count == {ELEMENT_WORDS_WIDTH{1'b1}})
119	                        next_state = S_WAIT;
120	                    else
121	                        next_state = S_FILL;
122	
123	                    if (mem_ack_i)
124	                        next_word_count = word_count + 1'b1;
125	                    else
126	                        next_word_count = word_count;
127	                end
128	
129	                S_WAIT: begin
130	                    next_state = S_IDLE;
131	                    next_word_count = 2'b00;
132	                end
133	            endcase
134	        end
135	    end
136	    
137	    // cache ctrl
138	    always @ (*) begin
139	        case(state)
140	            S_IDLE, S_WAIT: begin
141	                cache_addr = addr_rw;
142	                cache_load = en_r;
143	                cache_edit = en_w;
144	                cache_store = 1'b0;
145	                cache_u_b_h_w = u_b_h_w;
146	                cache_din = data_w;
147	            end
148	            S_BACK, S_PRE_BACK: begin
149	                cache_addr = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
150	                cache_load = 1'b0;
151	                cache_edit = 1'b0;
152	                cache_store = 1'b0;
153	                cache_u_b_h_w = 3'b010;
154	                cache_din = 32'b0;
155	            end
156	            S_FILL: begin
157	                cache_addr = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
158	                cache_load = 1'b0;
159	                cache_edit = 1'b0;
160	                cache_store = mem_ack_i;
161	                cache_u_b_h_w = 3'b010;
162	                cache_din = mem_data_i;
163	            end
164	        endcase
165	    end
166	    assign data_r = cache_dout;
167	
168	    // mem ctrl
169	    always @ (*) begin
170	        case (next_state)
171	            S_IDLE, S_PRE_BACK, S_WAIT: begin
172	                mem_cs_o = 1'b0;
173	                mem_we_o = 1'b0;
174	                mem_addr_o = 32'b0;
175	            end
176	
177	            S_BACK: begin
178	                mem_cs_o = 1'b1;
179	                mem_we_o = 1'b1;
180	                mem_addr_o = {cache_tag, addr_rw[ADDR_BITS-TAG_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
181	            end
182	
183	            S_FILL: begin
184	                mem_cs_o = 1'b1;
185	                mem_we_o = 1'b0;
186	                mem_addr_o = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
187	            end
188	        endcase
189	    end
190	    assign mem_data_o = cache_dout;
191	
192	    // stall the CPU until the access completes; in S_WAIT the cache
193	    // re-access happens on the negedge, so the pipeline can advance
194	    // at the end of that cycle
195	    assign stall = (en_r | en_w) & ~(state == S_IDLE & cache_hit) & ~(state == S_WAIT);
196	
197	endmodule

