// Functional verification TB for lab4 (5-stage pipeline + CMU cache).
// Monitors WB-stage register writes hierarchically inside RV32core and
// checks them against a hand-executed expected sequence, plus checks
// data_ram contents after the store block is evicted (write-back).
module tb_lab4;
    reg clk, rst;
    wire [31:0] debug_data, wb_pc, wb_inst;
    integer cycle = 0;
    integer errors = 0;
    integer exp_idx = 0;
    integer i;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'd0),
        .debug_data(debug_data),
        .clk(clk),
        .rst(rst),
        .wb_pc(wb_pc),
        .wb_inst(wb_inst),
        .mem_addr(),
        .mem_data(),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #6 rst = 0;
    end
    always #1 clk = ~clk;

    // ---------------- expected WB sequence (hand-executed) ----------------
    // ROM program:
    //  0x00 00000013  nop
    //  0x04 01c00083  lb  x1, 28(x0)    ; ram[7]=F0F0F0F0 -> byte0 F0 -> x1=FFFFFFF0
    //  0x08 01c01103  lh  x2, 28(x0)    ; half F0F0       -> x2=FFFFF0F0
    //  0x0c 01c02183  lw  x3, 28(x0)    ;                  x3=F0F0F0F0
    //  0x10 01c04203  lbu x4, 28(x0)    ;                  x4=000000F0
    //  0x14 01c05283  lhu x5, 28(x0)    ;                  x5=0000F0F0
    //  0x18 21002003  lw  x6, 0x210(x0) ; ram word 132 = 0 -> x6=00000000
    //  0x1c abcde0b7  lui x7, 0xabcde   ;                  x7=ABCDE000
    //  0x20 71c08093  addi x1, x1, 0x71c; FFFFFFF0+71C    -> x1=0000070C
    //  0x24 00100023  sb  x1, 0(x0)     ; mem[0].byte0 = 0C
    //  0x28 00101223  sh  x1, 4(x0)     ; mem[1].half  = 070C
    //  0x2c 00102423  sw  x1, 8(x0)     ; mem[2]       = 0000070C
    //  0x30 20002303  lw  x9, 0x200(x0) ; ram word 128 = 0 -> x9=0 (evicts set0)
    //  0x34 40002383  lw x10, 0x400(x0) ; ram word 256 = 0 -> x10=0 (evicts dirty blk0 -> write-back)
    //  0x38 41002403  lw x11, 0x410(x0) ; ram word 260 = 0 -> x11=0
    //  0x3c 0ed06813  ori x16, x0, 0xed ;                  x16=000000ED
    //  0x40 ffdff06f  jal x0, -4        ; self loop
    reg [31:0] exp_pc   [0:11];
    reg [4:0]  exp_rd   [0:11];
    reg [31:0] exp_data [0:11];
    localparam N_EXP = 9;
    initial begin
        exp_pc[0]=32'h04; exp_rd[0]=5'd1;  exp_data[0]=32'hFFFFFFF0;
        exp_pc[1]=32'h08; exp_rd[1]=5'd2;  exp_data[1]=32'hFFFFF0F0;
        exp_pc[2]=32'h0C; exp_rd[2]=5'd3;  exp_data[2]=32'hF0F0F0F0;
        exp_pc[3]=32'h10; exp_rd[3]=5'd4;  exp_data[3]=32'h000000F0;
        exp_pc[4]=32'h14; exp_rd[4]=5'd5;  exp_data[4]=32'h0000F0F0;
        exp_pc[5]=32'h18; exp_rd[5]=5'd6;  exp_data[5]=32'h00000000;
        exp_pc[6]=32'h1C; exp_rd[6]=5'd7;  exp_data[6]=32'hABCDE000;
        exp_pc[7]=32'h20; exp_rd[7]=5'd1;  exp_data[7]=32'h0000070C;
        exp_pc[8]=32'h3C; exp_rd[8]=5'd16; exp_data[8]=32'h000000ED;
    end

    // ------------- WB monitor: Regs commits writes on negedge clk -------------
    always @(negedge clk) begin
        if (!rst) begin
            cycle = cycle + 1;
            if (core.RegWrite_WB === 1'b1) begin
                // X/Z checks
                if (^core.wt_data_WB === 1'bx) begin
                    $display("ERROR cyc=%0d PC=%h: X/Z in wt_data_WB=%h", cycle, core.PC_WB, core.wt_data_WB);
                    errors = errors + 1;
                end
                if (^core.rd_WB === 1'bx || ^core.PC_WB === 1'bx) begin
                    $display("ERROR cyc=%0d: X/Z in rd_WB/PC_WB", cycle);
                    errors = errors + 1;
                end
                $display("WB cyc=%0d PC=%h rd=x%0d data=%h inst=%h",
                         cycle, core.PC_WB, core.rd_WB, core.wt_data_WB, core.inst_WB);
                if (core.rd_WB != 5'd0) begin
                    if (exp_idx >= N_EXP) begin
                        $display("ERROR cyc=%0d: unexpected extra WB PC=%h rd=x%0d data=%h",
                                 cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
                        errors = errors + 1;
                    end
                    else begin
                        if (core.PC_WB !== exp_pc[exp_idx] ||
                            core.rd_WB !== exp_rd[exp_idx] ||
                            core.wt_data_WB !== exp_data[exp_idx]) begin
                            $display("ERROR cyc=%0d: mismatch #%0d got PC=%h rd=x%0d data=%h, expected PC=%h rd=x%0d data=%h",
                                     cycle, exp_idx, core.PC_WB, core.rd_WB, core.wt_data_WB,
                                     exp_pc[exp_idx], exp_rd[exp_idx], exp_data[exp_idx]);
                            errors = errors + 1;
                        end
                        exp_idx = exp_idx + 1;
                    end
                end
            end
        end
    end

    // ------------- run long enough for cache misses / write-back -------------
    initial begin
        #4000;
        $display("----------------------------------------------------------");
        if (exp_idx != N_EXP) begin
            $display("ERROR: only %0d of %0d expected WB writes observed", exp_idx, N_EXP);
            errors = errors + 1;
        end
        // check store results reached data_ram via cache write-back
        // expected: data[0]=0000800C data[1]=0000070C data[2]=0000070C data[3]=00000014
        $display("data_ram[0..3] = %h %h %h %h",
                 core.RAM.data[0], core.RAM.data[1], core.RAM.data[2], core.RAM.data[3]);
        if (core.RAM.data[0] !== 32'h0000800C) begin
            $display("ERROR: data_ram[0]=%h expected 0000800C (sb write-back)", core.RAM.data[0]);
            errors = errors + 1;
        end
        if (core.RAM.data[1] !== 32'h0000070C) begin
            $display("ERROR: data_ram[1]=%h expected 0000070C (sh write-back)", core.RAM.data[1]);
            errors = errors + 1;
        end
        if (core.RAM.data[2] !== 32'h0000070C) begin
            $display("ERROR: data_ram[2]=%h expected 0000070C (sw write-back)", core.RAM.data[2]);
            errors = errors + 1;
        end
        if (core.RAM.data[3] !== 32'h00000014) begin
            $display("ERROR: data_ram[3]=%h expected 00000014 (untouched)", core.RAM.data[3]);
            errors = errors + 1;
        end
        // confirm the CPU is in the jal self-loop (program reached the end)
        if (core.PC_IF !== 32'h00000040 && core.PC_IF !== 32'h00000044) begin
            $display("WARNING: PC_IF=%h at end, expected to be spinning at 0x40", core.PC_IF);
        end
        if (errors == 0)
            $display("TB RESULT: PASS (all %0d expected WB writes matched, stores verified in RAM, no X/Z)", N_EXP);
        else
            $display("TB RESULT: FAIL (%0d errors)", errors);
        $finish;
    end

endmodule

